const grid=document.querySelector('#tool-grid'),search=document.querySelector('#search'),empty=document.querySelector('#empty');
let category='全部';
function render(){const q=search.value.trim().toLocaleLowerCase();const filtered=tools.filter(t=>(category==='全部'||t.category===category)&&(`${t.name} ${t.maker} ${t.category} ${t.desc}`).toLocaleLowerCase().includes(q));grid.replaceChildren(...filtered.map(t=>{const card=document.createElement('article');card.className='tool-card';card.style.setProperty('--tint',t.tint);card.style.setProperty('--ink',t.color);const top=document.createElement('div');top.className='card-top';const ico=document.createElement('div');ico.className='tool-icon';const logo=document.createElement('img');const domain=new URL(t.site).hostname;logo.src=`https://${domain}/favicon.ico`;logo.alt=`${t.name} Logo`;logo.loading='lazy';logo.referrerPolicy='no-referrer';logo.onerror=()=>{if(logo.dataset.fallback){logo.remove();ico.textContent=t.icon}else{logo.dataset.fallback='1';logo.src=`https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=128`}};ico.append(logo);const badge=document.createElement('span');badge.className='badge';badge.textContent=t.category;top.append(ico,badge);const h=document.createElement('h3');h.textContent=t.name;const maker=document.createElement('p');maker.className='maker';maker.textContent=t.maker;const desc=document.createElement('p');desc.className='desc';desc.textContent=t.desc;const links=document.createElement('div');links.className='card-links';for(const [label,url] of [['访问官网 ↗',t.site],['订阅入口 ↗',t.plan]]){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.textContent=label;links.append(a)}card.append(top,h,maker,desc,links);return card}));empty.hidden=filtered.length>0}
document.querySelectorAll('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{category=btn.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b===btn));render()}));search.addEventListener('input',render);
document.querySelectorAll('[data-quick]').forEach(btn=>btn.addEventListener('click',()=>{category=btn.dataset.quick;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===category));search.value='';render();document.querySelector('#explore').scrollIntoView({behavior:'smooth'})}));render();
document.querySelectorAll('[data-work-filter]').forEach(btn=>btn.addEventListener('click',()=>{const type=btn.dataset.workFilter;document.querySelectorAll('[data-work-filter]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-selected',String(b===btn))});document.querySelectorAll('[data-work-type]').forEach(card=>{card.hidden=card.dataset.workType!==type})}));
